-- Vaciamos la tabla y reiniciamos los IDs
TRUNCATE TABLE public.recipes RESTART IDENTITY CASCADE;

-- INICIAMOS UN ÚNICO INSERT PARA TODAS LAS RECETAS
INSERT INTO public.recipes (recipe_data) VALUES

('{"name": "Tostadas con Aguacate y Huevo", "meal_type": "desayuno", "price": "economica", "difficulty": "facil", "health": "saludable", "diet_type": "omnivoro", "allergens": ["gluten", "huevo"], "ingredients": [{"name": "Pan integral", "quantity": 2, "unit": "rebanadas"}, {"name": "Aguacate", "quantity": 0.5, "unit": "unidad"}, {"name": "Huevo", "quantity": 1, "unit": "unidad"}, {"name": "Aceite de oliva", "quantity": 5, "unit": "ml"}, {"name": "Sal", "quantity": 2, "unit": "g"}], "instructions": ["Tuesta las rebanadas de pan integral.", "Machaca el aguacate en un bol con un poco de sal.", "Cocina el huevo a la plancha con unas gotas de aceite de oliva.", "Unta el aguacate sobre las tostadas y coloca el huevo encima."]}'),
('{"name": "Avena con Plátano y Almendras", "meal_type": "desayuno", "price": "economica", "difficulty": "facil", "health": "saludable", "diet_type": "vegano", "allergens": ["frutos secos"], "ingredients": [{"name": "Copos de avena", "quantity": 50, "unit": "g"}, {"name": "Bebida de almendras", "quantity": 200, "unit": "ml"}, {"name": "Plátano", "quantity": 1, "unit": "unidad"}, {"name": "Almendras picadas", "quantity": 15, "unit": "g"}, {"name": "Canela en polvo", "quantity": 1, "unit": "g"}], "instructions": ["Calienta la bebida de almendras en un cazo e introduce la avena.", "Cocina a fuego lento durante 5 minutos removiendo constantemente hasta obtener una textura cremosa.", "Sirve en un bol, decora con rodajas de plátano, almendras picadas y una pizca de canela."]}'),
('{"name": "Tortitas Americanas Clásicas", "meal_type": "desayuno", "price": "economica", "difficulty": "intermedia", "health": "no saludable", "diet_type": "vegetariano", "allergens": ["gluten", "lactosa", "huevo"], "ingredients": [{"name": "Harina de trigo", "quantity": 150, "unit": "g"}, {"name": "Leche entera", "quantity": 200, "unit": "ml"}, {"name": "Huevo", "quantity": 1, "unit": "unidad"}, {"name": "Mantequilla", "quantity": 30, "unit": "g"}, {"name": "Azúcar", "quantity": 20, "unit": "g"}, {"name": "Levadura en polvo", "quantity": 8, "unit": "g"}], "instructions": ["Mezcla la harina, el azúcar y la levadura en un bol grande.", "En otro recipiente, bate el huevo y la leche, y añade la mantequilla derretida.", "Junta los ingredientes secos con los líquidos y bate hasta conseguir una masa sin grumos.", "Calienta una sartén con un poco de mantequilla y ve vertiendo porciones de masa. Dales la vuelta cuando salgan burbujas en la superficie y dora por el otro lado."]}'),
('{"name": "Huevos Rancheros", "meal_type": "desayuno", "price": "economica", "difficulty": "facil", "health": "saludable", "diet_type": "omnivoro", "allergens": ["huevo"], "ingredients": [{"name": "Huevo", "quantity": 2, "unit": "unidades"}, {"name": "Tortillas de maíz", "quantity": 2, "unit": "unidades"}, {"name": "Frijoles refritos", "quantity": 100, "unit": "g"}, {"name": "Tomate triturado", "quantity": 100, "unit": "g"}, {"name": "Cebolla", "quantity": 0.5, "unit": "unidad"}, {"name": "Chile jalapeño", "quantity": 10, "unit": "g"}, {"name": "Aceite de oliva", "quantity": 10, "unit": "ml"}], "instructions": ["Sofreír la cebolla picada y el chile jalapeño en una sartén con aceite.", "Añadir el tomate triturado y cocinar unos 5-7 minutos hasta obtener una salsa espesa.", "Calentar las tortillas de maíz y untar los frijoles refritos sobre ellas.", "Freír los dos huevos en una sartén y colocarlos sobre las tortillas. Bañar con la salsa de tomate caliente por encima."]}'),
('{"name": "Batido Verde Energizante", "meal_type": "desayuno", "price": "economica", "difficulty": "facil", "health": "saludable", "diet_type": "vegano", "allergens": [], "ingredients": [{"name": "Espinacas frescas", "quantity": 50, "unit": "g"}, {"name": "Manzana verde", "quantity": 1, "unit": "unidad"}, {"name": "Plátano", "quantity": 1, "unit": "unidad"}, {"name": "Agua de coco", "quantity": 250, "unit": "ml"}, {"name": "Semillas de chía", "quantity": 10, "unit": "g"}], "instructions": ["Lava bien las espinacas y la manzana verde.", "Corta la manzana en trozos medianos retirando las semillas.", "Pela el plátano y trocéalo.", "Coloca todos los ingredientes en la batidora junto con las semillas de chía y el agua de coco, y tritura hasta que quede homogéneo."]}'),
('{"name": "Pan con Tomate y Jamón Serrano", "meal_type": "desayuno", "price": "economica", "difficulty": "facil", "health": "saludable", "diet_type": "omnivoro", "allergens": ["gluten"], "ingredients": [{"name": "Pan rústico", "quantity": 2, "unit": "rebanadas"}, {"name": "Tomate maduro", "quantity": 1, "unit": "unidad"}, {"name": "Jamón serrano", "quantity": 50, "unit": "g"}, {"name": "Aceite de oliva virgen extra", "quantity": 15, "unit": "ml"}, {"name": "Sal", "quantity": 2, "unit": "g"}, {"name": "Ajo", "quantity": 1, "unit": "diente"}], "instructions": ["Tuesta las rebanadas de pan rústico.", "Corta un diente de ajo a la mitad y frótalo ligeramente sobre la miga de pan caliente.", "Ralla el tomate maduro en un bol y repártelo uniformemente sobre las rebanadas.", "Sazona con una pizca de sal y añade un buen chorro de aceite de oliva virgen extra.", "Coloca las lonchas de jamón serrano por encima y sirve inmediatamente."]}'),
('{"name": "Churros con Chocolate Caseros", "meal_type": "desayuno", "price": "economica", "difficulty": "intermedia", "health": "no saludable", "diet_type": "vegetariano", "allergens": ["gluten", "lactosa"], "ingredients": [{"name": "Harina de trigo", "quantity": 250, "unit": "g"}, {"name": "Agua", "quantity": 250, "unit": "ml"}, {"name": "Aceite de girasol para freír", "quantity": 500, "unit": "ml"}, {"name": "Chocolate negro para taza", "quantity": 150, "unit": "g"}, {"name": "Leche entera", "quantity": 400, "unit": "ml"}, {"name": "Sal", "quantity": 5, "unit": "g"}], "instructions": ["Pon a hervir el agua con la sal en un cazo. Cuando hierva, añade la harina de golpe y apaga el fuego.", "Remueve enérgicamente con una cuchara de madera hasta que la masa se desprenda de las paredes.", "Introduce la masa en una churrera o manga pastelera con boquilla de estrella para evitar bolsas de aire.", "Forma los churros y fríelos en abundante aceite de girasol muy caliente hasta que se doren. Escurre en papel absorbente.", "Para el chocolate: calienta la leche en un cazo, añade el chocolate troceado y remueve a fuego medio hasta que se disuelva por completo y espese."]}'),
('{"name": "Torrijas de Leche Tradicionales", "meal_type": "desayuno", "price": "economica", "difficulty": "intermedia", "health": "no saludable", "diet_type": "vegetariano", "allergens": ["gluten", "lactosa", "huevo"], "ingredients": [{"name": "Pan del día anterior", "quantity": 1, "unit": "barra"}, {"name": "Leche entera", "quantity": 1, "unit": "litro"}, {"name": "Azúcar", "quantity": 150, "unit": "g"}, {"name": "Canela en rama", "quantity": 1, "unit": "unidad"}, {"name": "Limón (piel)", "quantity": 1, "unit": "unidad"}, {"name": "Huevo", "quantity": 3, "unit": "unidades"}, {"name": "Aceite de oliva suave para freír", "quantity": 300, "unit": "ml"}, {"name": "Canela en polvo", "quantity": 10, "unit": "g"}], "instructions": ["Infusiona la leche en un cazo con 100g de azúcar, la rama de canela y la piel de limón limpia. Lleva a ebullición, apaga el fuego y deja enfriar.", "Corta la barra de pan en rodajas gruesas de unos 2 cm de grosor.", "Coloca las rodajas de pan en una fuente y báñalas con la leche infusionada fría hasta que queden bien empapadas.", "Pasa cada rebanada por huevo batido y fríelas en una sartén con abundante aceite de oliva suave muy caliente hasta dorar.", "Escurre el exceso de aceite y reboza las torrijas inmediatamente en una mezcla de azúcar restante y canela en polvo."]}'),
('{"name": "Lentejas Guisadas al Estilo Casero", "meal_type": "comida", "price": "economica", "difficulty": "facil", "health": "saludable", "diet_type": "vegetariano", "allergens": [], "ingredients": [{"name": "Lentejas secas", "quantity": 200, "unit": "g"}, {"name": "Zanahoria", "quantity": 2, "unit": "unidades"}, {"name": "Patata", "quantity": 1, "unit": "unidad"}, {"name": "Pimiento verde", "quantity": 1, "unit": "unidad"}, {"name": "Cebolla", "quantity": 1, "unit": "unidad"}, {"name": "Ajo", "quantity": 2, "unit": "dientes"}, {"name": "Tomate maduro", "quantity": 1, "unit": "unidad"}, {"name": "Pimentón dulce", "quantity": 5, "unit": "g"}, {"name": "Laurel", "quantity": 1, "unit": "hoja"}, {"name": "Aceite de oliva", "quantity": 20, "unit": "ml"}], "instructions": ["Pon las lentejas a remojo 2 horas antes si no usas lentejas rápidas.", "Trocea la cebolla, el pimiento, la zanahoria y el tomate.", "En una cazuela, sofríe la cebolla, los dientes de ajo y el pimiento con el aceite de oliva.", "Añade la zanahoria, el tomate, el pimentón y el laurel. Rehoga 2 minutos.", "Introduce las lentejas, la patata chascada en dados y cubre con agua fría. Cocina a fuego lento durante 45 minutos hasta que estén tiernas."]}'),
('{"name": "Paella de Marisco Premium", "meal_type": "comida", "price": "cara", "difficulty": "dificil", "health": "saludable", "diet_type": "pescetariano", "allergens": ["marisco", "pescado"], "ingredients": [{"name": "Arroz bomba", "quantity": 250, "unit": "g"}, {"name": "Caldo de pescado", "quantity": 750, "unit": "ml"}, {"name": "Langostinos", "quantity": 8, "unit": "unidades"}, {"name": "Mejillones", "quantity": 8, "unit": "unidades"}, {"name": "Calamar", "quantity": 150, "unit": "g"}, {"name": "Tomate maduro", "quantity": 1, "unit": "unidad"}, {"name": "Ajo", "quantity": 2, "unit": "dientes"}, {"name": "Azafrán en hebras", "quantity": 0.2, "unit": "g"}, {"name": "Pimiento verde", "quantity": 1, "unit": "unidad"}, {"name": "Aceite de oliva", "quantity": 40, "unit": "ml"}], "instructions": ["Limpia los mejillones abriéndolos al vapor y reserva el agua.", "En una paella con aceite, sofríe los langostinos enteros 2 minutos y retira.", "En el mismo aceite, sofríe el ajo, el pimiento picado y el calamar en dados.", "Añade el tomate rallado y rehoga. Agrega el azafrán e incorpora el arroz bomba, sofríelo 1 minuto.", "Moja con el caldo de pescado caliente e incorpora los langostinos y mejillones. Cocina 18 minutos."]}'),
('{"name": "Salmón al Horno con Verduras", "meal_type": "comida", "price": "cara", "difficulty": "facil", "health": "saludable", "diet_type": "pescetariano", "allergens": ["pescado"], "ingredients": [{"name": "Lomo de salmón fresco", "quantity": 300, "unit": "g"}, {"name": "Calabacín", "quantity": 1, "unit": "unidad"}, {"name": "Zanahoria", "quantity": 1, "unit": "unidad"}, {"name": "Pimiento rojo", "quantity": 0.5, "unit": "unidad"}, {"name": "Aceite de oliva", "quantity": 15, "unit": "ml"}, {"name": "Sal", "quantity": 3, "unit": "g"}, {"name": "Pimienta negra", "quantity": 2, "unit": "g"}], "instructions": ["Precalienta el horno a 200°C.", "Corta el calabacín, la zanahoria y el pimiento rojo en rodajas o bastones finos.", "Coloca las verduras en una bandeja de horno, alíñalas con sal, pimienta y la mitad del aceite de oliva.", "Coloca el lomo de salmón encima de las verduras, salpimienta y añade el resto del aceite por encima.", "Hornea durante 15 minutos hasta que el pescado esté cocinado y las verduras tiernas."]}'),
('{"name": "Gazpacho Andaluz Tradicional", "meal_type": "comida", "price": "economica", "difficulty": "facil", "health": "saludable", "diet_type": "vegano", "allergens": ["gluten"], "ingredients": [{"name": "Tomates pera maduros", "quantity": 1000, "unit": "g"}, {"name": "Pimiento verde italiano", "quantity": 1, "unit": "unidad"}, {"name": "Pepino", "quantity": 0.5, "unit": "unidad"}, {"name": "Ajo", "quantity": 1, "unit": "diente"}, {"name": "Pan duro", "quantity": 50, "unit": "g"}, {"name": "Aceite de oliva virgen extra", "quantity": 50, "unit": "ml"}, {"name": "Vinagre de Jerez", "quantity": 25, "unit": "ml"}, {"name": "Sal", "quantity": 5, "unit": "g"}], "instructions": ["Lava bien los tomates y el pimiento. Pela el pepino y el diente de ajo.", "Trocea todos los ingredientes y colócalos en el vaso de la batidora junto con el pan duro previamente remojado en agua.", "Tritura todo a máxima potencia hasta conseguir una crema muy fina y homogénea.", "Añade el vinagre de Jerez, la sal y, sin dejar de batir, vierte el aceite de oliva poco a poco para que emulsione.", "Pasa el gazpacho por un colador fino o chino para retirar cualquier resto de pieles o pepitas.", "Reserva en la nevera al menos 2 horas y sirve bien frío."]}'),
('{"name": "Lentejas a la Riojana con Chorizo", "meal_type": "comida", "price": "economica", "difficulty": "facil", "health": "saludable", "diet_type": "omnivoro", "allergens": [], "ingredients": [{"name": "Lentejas pardinas", "quantity": 250, "unit": "g"}, {"name": "Chorizo fresco", "quantity": 100, "unit": "g"}, {"name": "Patata", "quantity": 1, "unit": "unidad"}, {"name": "Zanahoria", "quantity": 1, "unit": "unidad"}, {"name": "Cebolla", "quantity": 0.5, "unit": "unidad"}, {"name": "Pimiento verde", "quantity": 0.5, "unit": "unidad"}, {"name": "Ajo", "quantity": 2, "unit": "dientes"}, {"name": "Pimentón de la Vera", "quantity": 5, "unit": "g"}, {"name": "Laurel", "quantity": 1, "unit": "hoja"}, {"name": "Aceite de oliva", "quantity": 20, "unit": "ml"}, {"name": "Sal", "quantity": 4, "unit": "g"}], "instructions": ["En una olla con un chorrito de aceite de oliva, sofríe el ajo picado, la cebolla y el pimiento cortados muy finos.", "Añade la zanahoria en rodajas y el chorizo cortado en rodajas gruesas. Rehoga un par de minutos.", "Introduce la patata pelada y cascada en trozos pequeños.", "Incorpora las lentejas limpias (no necesitan remojo previo si son pardinas), la hoja de laurel y el pimentón dulce. Remueve rápidamente.", "Cubre todo con agua fría (unos dos dedos por encima del nivel de las lentejas).", "Pon a fuego fuerte hasta que hierva, luego baja a fuego suave, tapa la olla y cocina unos 40-45 minutos. Sazona al gusto al final."]}'),
('{"name": "Marmitako de Atún del Cantábrico", "meal_type": "comida", "price": "economica", "difficulty": "intermedia", "health": "saludable", "diet_type": "pescetariano", "allergens": ["pescado"], "ingredients": [{"name": "Atún fresco limpio", "quantity": 300, "unit": "g"}, {"name": "Patatas", "quantity": 500, "unit": "g"}, {"name": "Cebolla", "quantity": 1, "unit": "unidad"}, {"name": "Pimiento verde italiano", "quantity": 1, "unit": "unidad"}, {"name": "Carne de pimiento choricero", "quantity": 15, "unit": "g"}, {"name": "Ajo", "quantity": 2, "unit": "dientes"}, {"name": "Caldo de pescado", "quantity": 500, "unit": "ml"}, {"name": "Vino blanco", "quantity": 50, "unit": "ml"}, {"name": "Aceite de oliva", "quantity": 30, "unit": "ml"}, {"name": "Sal", "quantity": 4, "unit": "g"}], "instructions": ["Sofreír la cebolla, el pimiento verde y el ajo picados finamente en una cazuela con aceite de oliva.", "Casca las patatas con el cuchillo y añádelas al sofrito.", "Añade la pulpa de pimiento choricero, el vino blanco y remueve durante dos minutos.", "Cubre las patatas con el caldo de pescado caliente y una pizca de sal. Cocina a fuego lento durante 25 minutos hasta que estén tiernas.", "Corta el atún en dados medianos limpios. Añádelos a la cazuela, apaga el fuego inmediatamente y tapa la olla.", "Deja reposar 5 minutos. El atún se cocinará en su punto exacto solo con el calor residual."]}'),
('{"name": "Carrilleras de Cerdo al Vino Tinto", "meal_type": "comida", "price": "cara", "difficulty": "intermedia", "health": "saludable", "diet_type": "omnivoro", "allergens": ["gluten"], "ingredients": [{"name": "Carrilleras de cerdo", "quantity": 500, "unit": "g"}, {"name": "Vino tinto de calidad", "quantity": 300, "unit": "ml"}, {"name": "Cebolla", "quantity": 1, "unit": "unidad"}, {"name": "Zanahoria", "quantity": 2, "unit": "unidades"}, {"name": "Puerro", "quantity": 1, "unit": "unidad"}, {"name": "Caldo de carne", "quantity": 250, "unit": "ml"}, {"name": "Harina de trigo", "quantity": 30, "unit": "g"}, {"name": "Aceite de oliva", "quantity": 40, "unit": "ml"}, {"name": "Sal", "quantity": 5, "unit": "g"}, {"name": "Pimienta negra", "quantity": 2, "unit": "g"}], "instructions": ["Limpia y salpimentar las carrilleras. Pásalas ligeramente por harina sacudiendo el exceso.", "En una olla rápida o tradicional con aceite de oliva, séllalas a fuego fuerte hasta que se doren y resérvalas.", "En el mismo aceite, sofríe la cebolla, puerro y zanahorias cortadas en trozos medianos unos 10 minutos.", "Vuelve a introducir la carne, vierte el vino tinto y deja reducir el alcohol a fuego fuerte durante 5 minutos.", "Añade el caldo de carne. Tapa y cocina (40 minutos en olla a presión o 2 horas a fuego lento tradicional).", "Saca la carne tierna de la olla. Tritura la salsa con la batidora para que quede muy fina y reduce si es necesario.", "Devuelve las carrilleras a la salsa caliente y sirve acompañadas de puré de patata."]}'),
('{"name": "Fabada Asturiana Tradicional", "meal_type": "comida", "price": "cara", "difficulty": "intermedia", "health": "saludable", "diet_type": "omnivoro", "allergens": [], "ingredients": [{"name": "Fabes asturianas", "quantity": 300, "unit": "g"}, {"name": "Chorizo asturiano", "quantity": 1, "unit": "unidad"}, {"name": "Morcilla asturiana", "quantity": 1, "unit": "unidad"}, {"name": "Tocino veteado", "quantity": 100, "unit": "g"}, {"name": "Lacón curado", "quantity": 100, "unit": "g"}, {"name": "Ajo", "quantity": 2, "unit": "dientes"}, {"name": "Azafrán en hebra", "quantity": 0.2, "unit": "g"}, {"name": "Laurel", "quantity": 1, "unit": "hoja"}], "instructions": ["Pon las fabes a remojo en agua fría la noche anterior. Remoja el lacón aparte en agua templada.", "Escurre las fabes y colócalas en una cazuela ancha. Añade el chorizo, la morcilla, el tocino y el lacón.", "Cubre todo con agua fría hasta que sobrepase un par de dedos las alubias. Añade los dientes de ajo enteros y el laurel.", "Lueva a ebullición fuerte espumando las impurezas de la superficie.", "Al comenzar a hervir, añade un chorro de agua fría para romper el hervor. Repite esto una vez más.", "Tapa y cocina a fuego muy lento durante 2 a 3 horas sin remover con cuchara (sino agitando la cazuela).", "Disuelve el azafrán en un poco de caldo caliente y añádelo la última media hora. Rectifica de sal al final."]}'),
('{"name": "Cocido Madrileño Completo", "meal_type": "comida", "price": "cara", "difficulty": "dificil", "health": "saludable", "diet_type": "omnivoro", "allergens": ["gluten"], "ingredients": [{"name": "Garbanzos castellanos", "quantity": 250, "unit": "g"}, {"name": "Morcillo de ternera", "quantity": 300, "unit": "g"}, {"name": "Chorizo dulce", "quantity": 1, "unit": "unidad"}, {"name": "Morcilla de cebolla", "quantity": 1, "unit": "unidad"}, {"name": "Tocino blanco salado", "quantity": 100, "unit": "g"}, {"name": "Hueso de jamón", "quantity": 1, "unit": "unidad"}, {"name": "Pechuga de pollo", "quantity": 150, "unit": "g"}, {"name": "Patatas medianas", "quantity": 2, "unit": "unidades"}, {"name": "Zanahorias", "quantity": 2, "unit": "unidades"}, {"name": "Repollo", "quantity": 200, "unit": "g"}, {"name": "Fideos para sopa", "quantity": 80, "unit": "g"}, {"name": "Sal", "quantity": 6, "unit": "g"}], "instructions": ["Pon a remojo los garbanzos en agua templada con sal la noche anterior.", "En una olla grande, pon el morcillo, el tocino, los huesos y el pollo con abundante agua fría. Lleva a ebullición y retira toda la espuma.", "Cuando hierva, añade los garbanzos escurridos. Tapa y cocina a fuego lento durante 2 horas.", "Introduce el chorizo, las patatas peladas y las zanahorias limpias. Cocina otros 30 minutos.", "En una olla aparte, cuece el repollo picado junto con la morcilla para que no tiña el caldo principal.", "Cuela el caldo del cocido a otra cazuela, añade los fideos finos y cuece durante 3 minutos para hacer la sopa.", "Sirve en tres vuelcos: primero la sopa de fideos caliente; segundo los garbanzos, patatas y repollo salteado; tercero las carnes trinchadas."]}'),
('{"name": "Pulpo a la Gallega (Feira)", "meal_type": "comida", "price": "cara", "difficulty": "intermedia", "health": "saludable", "diet_type": "pescetariano", "allergens": ["pescado"], "ingredients": [{"name": "Pulpo cocido (patas)", "quantity": 400, "unit": "g"}, {"name": "Patatas medianas", "quantity": 3, "unit": "unidades"}, {"name": "Aceite de oliva virgen extra", "quantity": 30, "unit": "ml"}, {"name": "Pimentón dulce", "quantity": 5, "unit": "g"}, {"name": "Pimentón picante", "quantity": 2, "unit": "g"}, {"name": "Sal gruesa", "quantity": 5, "unit": "g"}], "instructions": ["Cuece las patatas peladas y cortadas en rodajas gruesas en abundante agua con sal durante 15 minutos.", "Calienta las patas de pulpo cocidas pasándolas por vapor o sumergiéndolas brevemente en agua caliente.", "Coloca una cama de patatas cocidas calientes en un plato.", "Corta el pulpo tibio con unas tijeras en rodajas finas sobre la cama de patatas.", "Riega generosamente todo el plato con aceite de oliva virgen extra.", "Espolvorea la mezcla de pimentón dulce y picante, y termina con escamas de sal gruesa."]}'),
('{"name": "Bacalao al Pil Pil Tradicional", "meal_type": "comida", "price": "cara", "difficulty": "dificil", "health": "saludable", "diet_type": "pescetariano", "allergens": ["pescado"], "ingredients": [{"name": "Lomos de bacalao desalado", "quantity": 400, "unit": "g"}, {"name": "Aceite de oliva virgen extra", "quantity": 150, "unit": "ml"}, {"name": "Dientes de ajo", "quantity": 4, "unit": "unidades"}, {"name": "Guindilla seca", "quantity": 1, "unit": "unidad"}], "instructions": ["Pela y lamina los dientes de ajo. En una cazuela de barro, calienta el aceite y dora los ajos y la guindilla.", "Retira los ajos y la guindilla una vez dorados y resérvalos.", "En el mismo aceite templado, coloca los lomos de bacalao con la piel hacia arriba. Cocina a fuego mínimo 4 minutos, dales la vuelta y cocina otros 4 minutos.", "Saca los lomos de bacalao a un plato.", "Espera a que el aceite esté templado y remueve en círculos con un colador de alambre para ligar la gelatina con el aceite hasta conseguir una salsa espesa.", "Devuelve el bacalao, decora con los ajos y la guindilla, y calienta suavemente."]}'),
('{"name": "Albóndigas en Salsa Española", "meal_type": "comida", "price": "economica", "difficulty": "intermedia", "health": "saludable", "diet_type": "omnivoro", "allergens": ["gluten", "huevo"], "ingredients": [{"name": "Carne picada mixta", "quantity": 500, "unit": "g"}, {"name": "Cebolla", "quantity": 1, "unit": "unidad"}, {"name": "Ajo", "quantity": 2, "unit": "dientes"}, {"name": "Zanahoria", "quantity": 1, "unit": "unidad"}, {"name": "Pan rallado", "quantity": 30, "unit": "g"}, {"name": "Huevo", "quantity": 1, "unit": "unidad"}, {"name": "Vino blanco", "quantity": 100, "unit": "ml"}, {"name": "Caldo de carne", "quantity": 400, "unit": "ml"}, {"name": "Harina", "quantity": 50, "unit": "g"}], "instructions": ["Mezcla la carne picada con el huevo, pan rallado, sal, pimienta y ajo muy picado. Forma las albóndigas.", "Pásalas por harina y fríelas ligeramente para sellarlas. Reserva.", "En la misma sartén, sofríe la cebolla y zanahoria picadas. Añade una cucharada de harina y tuesta.", "Vierte el vino blanco y deja evaporar el alcohol. Añade el caldo y tritura la salsa.", "Introduce las albóndigas en la salsa y cuece a fuego lento 20 minutos."]}'),
('{"name": "Fideuá de Marisco", "meal_type": "comida", "price": "cara", "difficulty": "intermedia", "health": "saludable", "diet_type": "pescetariano", "allergens": ["gluten", "marisco", "pescado"], "ingredients": [{"name": "Fideos gruesos para fideuá", "quantity": 300, "unit": "g"}, {"name": "Caldo de pescado", "quantity": 800, "unit": "ml"}, {"name": "Gambas arroceras", "quantity": 200, "unit": "g"}, {"name": "Sepia", "quantity": 1, "unit": "unidad"}, {"name": "Mejillones", "quantity": 250, "unit": "g"}, {"name": "Tomate frito", "quantity": 50, "unit": "g"}, {"name": "Pimentón dulce", "quantity": 5, "unit": "g"}], "instructions": ["En una paellera, tuesta los fideos con un poco de aceite hasta que estén dorados. Retira y reserva.", "Corta la sepia en dados y sofríela. Añade las gambas un minuto y saca las gambas.", "Agrega el pimentón y el tomate frito a la sepia. Remueve rápido.", "Vuelve a poner los fideos, añade el caldo caliente y los mejillones limpios.", "Cocina a fuego medio-fuerte hasta que los fideos absorban el caldo y se queden de punta."]}'),
('{"name": "Ensaladilla Rusa Clásica", "meal_type": "comida", "price": "economica", "difficulty": "facil", "health": "no saludable", "diet_type": "omnivoro", "allergens": ["huevo", "pescado"], "ingredients": [{"name": "Patatas", "quantity": 500, "unit": "g"}, {"name": "Zanahoria", "quantity": 2, "unit": "unidades"}, {"name": "Atún en conserva", "quantity": 150, "unit": "g"}, {"name": "Huevos", "quantity": 3, "unit": "unidades"}, {"name": "Guisantes", "quantity": 50, "unit": "g"}, {"name": "Mayonesa", "quantity": 200, "unit": "g"}, {"name": "Aceitunas rellenas", "quantity": 50, "unit": "g"}], "instructions": ["Cuece las patatas y zanahorias enteras con piel hasta que estén tiernas. Cuece también los huevos.", "Pela y corta en dados pequeños las patatas, zanahorias y huevos (reserva una yema para decorar).", "Mezcla en un bol grande la patata, zanahoria, atún escurrido, guisantes, huevo y aceitunas picadas.", "Añade la mayonesa y mezcla todo con movimientos envolventes.", "Decora con la yema rallada por encima y sirve muy fría."]}'),
('{"name": "Pollo al Ajillo", "meal_type": "comida", "price": "economica", "difficulty": "facil", "health": "saludable", "diet_type": "omnivoro", "allergens": [], "ingredients": [{"name": "Pollo troceado", "quantity": 1000, "unit": "g"}, {"name": "Ajos", "quantity": 10, "unit": "dientes"}, {"name": "Vino blanco", "quantity": 150, "unit": "ml"}, {"name": "Perejil fresco", "quantity": 10, "unit": "g"}, {"name": "Aceite de oliva", "quantity": 50, "unit": "ml"}, {"name": "Sal", "quantity": 5, "unit": "g"}, {"name": "Pimienta", "quantity": 2, "unit": "g"}], "instructions": ["Salpimienta los trozos de pollo limpio.", "Da un golpe a los dientes de ajo sin pelarlos y fríelos en aceite. Retíralos cuando doren.", "En el mismo aceite, fríe el pollo a fuego fuerte hasta que esté muy crujiente y dorado por todas partes.", "Devuelve los ajos a la sartén, vierte el vino blanco y deja reducir 10 minutos a fuego medio.", "Espolvorea con abundante perejil fresco picado y sirve caliente."]}'),
('{"name": "Calamares en su Tinta", "meal_type": "comida", "price": "cara", "difficulty": "intermedia", "health": "saludable", "diet_type": "pescetariano", "allergens": ["marisco", "pescado"], "ingredients": [{"name": "Calamares limpios", "quantity": 600, "unit": "g"}, {"name": "Bolsitas de tinta de calamar", "quantity": 2, "unit": "unidades"}, {"name": "Cebolla", "quantity": 2, "unit": "unidades"}, {"name": "Ajo", "quantity": 2, "unit": "dientes"}, {"name": "Vino blanco", "quantity": 100, "unit": "ml"}, {"name": "Tomate frito", "quantity": 50, "unit": "g"}, {"name": "Agua o caldo de pescado", "quantity": 200, "unit": "ml"}], "instructions": ["Corta los calamares en aros medianos.", "Pocha a fuego muy lento la cebolla y el ajo muy picados hasta que estén transparentes.", "Añade los calamares y rehoga 5 minutos. Incorpora el tomate frito y el vino blanco. Deja reducir.", "Disuelve la tinta en el caldo de pescado caliente y viértelo en la olla.", "Cocina a fuego lento durante unos 40 minutos hasta que el calamar esté muy tierno y la salsa negra espese."]}'),
('{"name": "Rabo de Toro Estofado", "meal_type": "comida", "price": "cara", "difficulty": "dificil", "health": "saludable", "diet_type": "omnivoro", "allergens": ["gluten"], "ingredients": [{"name": "Rabo de ternera o toro", "quantity": 1000, "unit": "g"}, {"name": "Vino tinto", "quantity": 500, "unit": "ml"}, {"name": "Cebolla", "quantity": 2, "unit": "unidades"}, {"name": "Zanahoria", "quantity": 2, "unit": "unidades"}, {"name": "Pimiento rojo", "quantity": 1, "unit": "unidad"}, {"name": "Puerro", "quantity": 1, "unit": "unidad"}, {"name": "Caldo de carne", "quantity": 500, "unit": "ml"}, {"name": "Harina", "quantity": 40, "unit": "g"}], "instructions": ["Salpimienta los trozos de rabo, pásalos por harina y dóralos a fuego fuerte en una olla. Reserva la carne.", "En el mismo aceite, sofríe todas las verduras troceadas gruesas durante 15 minutos.", "Vuelve a meter la carne, riega con el vino tinto y deja hervir 10 minutos para evaporar el alcohol.", "Añade el caldo de carne, tapa la olla y cuece a fuego muy lento durante 3-4 horas (o 1 hora en olla exprés) hasta que la carne se separe del hueso.", "Retira la carne, tritura la salsa, redúcela si hace falta y vuelve a juntarlo todo."]}'),
('{"name": "Migas Extremeñas", "meal_type": "comida", "price": "economica", "difficulty": "intermedia", "health": "no saludable", "diet_type": "omnivoro", "allergens": ["gluten"], "ingredients": [{"name": "Pan duro (de candeal)", "quantity": 400, "unit": "g"}, {"name": "Panceta curada", "quantity": 150, "unit": "g"}, {"name": "Chorizo", "quantity": 150, "unit": "g"}, {"name": "Ajos", "quantity": 6, "unit": "dientes"}, {"name": "Pimentón de la Vera", "quantity": 5, "unit": "g"}, {"name": "Aceite de oliva", "quantity": 60, "unit": "ml"}, {"name": "Agua templada con sal", "quantity": 150, "unit": "ml"}], "instructions": ["Corta el pan duro en dados muy pequeños, humedécelo ligeramente con el agua salada y tápalo con un paño un par de horas.", "En una sartén grande y profunda, fríe los ajos enteros con corte, la panceta en tiras y el chorizo en dados. Saca y reserva.", "En esa misma grasa, retira la sartén del fuego, echa el pimentón y revuelve para que no se queme.", "Añade las migas de pan y cocina a fuego lento sin parar de remover con la rasera (unos 30-40 min) hasta que queden sueltas y crujientes.", "Añade de nuevo la carne y los ajos, mezcla bien y sirve. Acompáñalas tradicionalmente con uvas o huevo frito."]}'),
('{"name": "Arroz a Banda", "meal_type": "comida", "price": "cara", "difficulty": "intermedia", "health": "saludable", "diet_type": "pescetariano", "allergens": ["pescado", "marisco"], "ingredients": [{"name": "Arroz bomba", "quantity": 300, "unit": "g"}, {"name": "Caldo o fumet de pescado (morralla)", "quantity": 900, "unit": "ml"}, {"name": "Ñora", "quantity": 1, "unit": "unidad"}, {"name": "Ajos", "quantity": 3, "unit": "dientes"}, {"name": "Tomate rallado", "quantity": 100, "unit": "g"}, {"name": "Sepia limpia", "quantity": 200, "unit": "g"}, {"name": "Azafrán", "quantity": 0.2, "unit": "g"}], "instructions": ["Fríe la ñora sin semillas en aceite y pícala en un mortero con un diente de ajo.", "En la paella, sofríe la sepia troceada muy pequeña. Añade el resto de ajo picado y el tomate rallado.", "Incorpora el majado de ñora y el azafrán.", "Añade el arroz y sofríelo para sellar el grano.", "Vierte el caldo de pescado hirviendo (doble y medio que de arroz). Cuece a fuego fuerte 8 minutos y a fuego suave 10 minutos. Deja reposar."]}'),
('{"name": "Empanada Gallega de Atún", "meal_type": "comida", "price": "economica", "difficulty": "intermedia", "health": "saludable", "diet_type": "pescetariano", "allergens": ["gluten", "pescado", "huevo"], "ingredients": [{"name": "Masa de empanada", "quantity": 2, "unit": "láminas"}, {"name": "Atún en conserva", "quantity": 300, "unit": "g"}, {"name": "Cebolla", "quantity": 2, "unit": "unidades"}, {"name": "Pimiento rojo", "quantity": 1, "unit": "unidad"}, {"name": "Tomate frito", "quantity": 100, "unit": "g"}, {"name": "Huevo cocido", "quantity": 2, "unit": "unidades"}, {"name": "Huevo para pintar", "quantity": 1, "unit": "unidad"}], "instructions": ["Pocha la cebolla y el pimiento finamente picados a fuego lento hasta que estén muy tiernos.", "Añade el tomate frito y el atún escurrido. Mezcla bien y deja enfriar.", "Añade los huevos cocidos picados a la mezcla.", "Extiende una lámina de masa, reparte el relleno dejando los bordes libres y cubre con la otra lámina.", "Cierra los bordes haciendo un repulgue, pincha la superficie con un tenedor, pinta con huevo batido y hornea a 200°C unos 30 minutos."]}'),
('{"name": "Espinacas con Garbanzos a la Andaluza", "meal_type": "comida", "price": "economica", "difficulty": "facil", "health": "saludable", "diet_type": "vegano", "allergens": ["gluten"], "ingredients": [{"name": "Garbanzos cocidos", "quantity": 400, "unit": "g"}, {"name": "Espinacas frescas o congeladas", "quantity": 300, "unit": "g"}, {"name": "Ajo", "quantity": 3, "unit": "dientes"}, {"name": "Pan duro", "quantity": 2, "unit": "rebanadas"}, {"name": "Comino molido", "quantity": 5, "unit": "g"}, {"name": "Pimentón dulce", "quantity": 5, "unit": "g"}, {"name": "Vinagre", "quantity": 15, "unit": "ml"}], "instructions": ["Cuece las espinacas unos minutos y escúrrelas muy bien.", "Fríe los ajos enteros y las rebanadas de pan. Retira al mortero y maja con el comino, vinagre y un poco de agua.", "En el mismo aceite (apartado del fuego), echa el pimentón dulce. Añade rápidamente las espinacas y rehoga.", "Incorpora el majado del mortero y los garbanzos escurridos.", "Cocina todo junto a fuego suave 10 minutos para que se mezclen los sabores."]}'),
('{"name": "Cachopo Asturiano Tradicional", "meal_type": "comida", "price": "cara", "difficulty": "intermedia", "health": "no saludable", "diet_type": "omnivoro", "allergens": ["gluten", "lactosa", "huevo"], "ingredients": [{"name": "Filetes de ternera finos (tapa o babilla)", "quantity": 2, "unit": "unidades grand"}, {"name": "Jamón serrano", "quantity": 4, "unit": "lonchas"}, {"name": "Queso tierno en lonchas (tipo oscos)", "quantity": 4, "unit": "lonchas"}, {"name": "Harina de trigo", "quantity": 100, "unit": "g"}, {"name": "Huevo", "quantity": 2, "unit": "unidades"}, {"name": "Pan rallado", "quantity": 150, "unit": "g"}], "instructions": ["Espalma los filetes de ternera golpeándolos para afinarlos y salpimienta ligeramente (el jamón ya aporta sal).", "Sobre un filete, coloca una capa de lonchas de jamón, luego el queso y cubre con el otro filete.", "Presiona bien los bordes para que quede cerrado.", "Pasa el cachopo entero por harina, luego por huevo batido y finalmente por pan rallado, presionando para que se adhiera.", "Fríe en una sartén grande con abundante aceite a fuego medio-fuerte unos 3-4 minutos por lado hasta que esté muy dorado."]}'),
('{"name": "Bacalao a la Vizcaína", "meal_type": "comida", "price": "cara", "difficulty": "intermedia", "health": "saludable", "diet_type": "pescetariano", "allergens": ["pescado", "gluten"], "ingredients": [{"name": "Lomos de bacalao desalado", "quantity": 400, "unit": "g"}, {"name": "Cebollas moradas", "quantity": 4, "unit": "unidades"}, {"name": "Pimientos choriceros (pulpa)", "quantity": 4, "unit": "cucharadas"}, {"name": "Ajo", "quantity": 2, "unit": "dientes"}, {"name": "Pan duro (galleta maría o biscotes)", "quantity": 20, "unit": "g"}, {"name": "Aceite de oliva", "quantity": 50, "unit": "ml"}], "instructions": ["Corta las cebollas moradas en juliana muy fina y póchalas a fuego muy lento con el ajo durante casi 1 hora, hasta que caramelicen.", "Añade la pulpa de los pimientos choriceros (previamente hidratados y rascados).", "Incorpora un poco de pan tostado desmigado para espesar la salsa y tritura (opcional, tradicionalmente no se tritura pero queda más fina).", "Pasa el bacalao por harina y séllalo vuelta y vuelta en otra sartén.", "Introduce el bacalao en la cazuela con la salsa vizcaína y cocina a fuego muy suave 10 minutos."]}'),
('{"name": "Pollo al Chilindrón", "meal_type": "comida", "price": "economica", "difficulty": "facil", "health": "saludable", "diet_type": "omnivoro", "allergens": [], "ingredients": [{"name": "Pollo troceado", "quantity": 1000, "unit": "g"}, {"name": "Pimiento rojo", "quantity": 1, "unit": "unidad"}, {"name": "Pimiento verde", "quantity": 1, "unit": "unidad"}, {"name": "Cebolla", "quantity": 1, "unit": "unidad"}, {"name": "Ajo", "quantity": 3, "unit": "dientes"}, {"name": "Tomates maduros o triturado", "quantity": 400, "unit": "g"}, {"name": "Vino blanco", "quantity": 100, "unit": "ml"}, {"name": "Jamón serrano en tacos", "quantity": 50, "unit": "g"}], "instructions": ["Salpimienta los trozos de pollo y dóralos a fuego fuerte en una cazuela. Retira y reserva.", "En la misma cazuela, sofríe la cebolla, el ajo y los pimientos cortados en tiras. Añade el jamón.", "Cuando la verdura esté pochada, vuelve a meter el pollo y vierte el vino blanco. Deja evaporar.", "Añade el tomate triturado, baja el fuego, tapa y deja guisar unos 40 minutos hasta que el pollo esté muy tierno y la salsa haya espesado."]}'),
('{"name": "Guiso de Papas con Chocos", "meal_type": "comida", "price": "economica", "difficulty": "facil", "health": "saludable", "diet_type": "pescetariano", "allergens": ["marisco"], "ingredients": [{"name": "Choco o sepia limpia", "quantity": 500, "unit": "g"}, {"name": "Patatas", "quantity": 800, "unit": "g"}, {"name": "Cebolla", "quantity": 1, "unit": "unidad"}, {"name": "Ajo", "quantity": 2, "unit": "dientes"}, {"name": "Pimiento verde", "quantity": 1, "unit": "unidad"}, {"name": "Pimentón dulce", "quantity": 5, "unit": "g"}, {"name": "Vino blanco", "quantity": 100, "unit": "ml"}, {"name": "Guisantes (opcional)", "quantity": 100, "unit": "g"}], "instructions": ["Corta el choco en trozos cuadrados medianos.", "Prepara un sofrito picando muy fino la cebolla, ajo y pimiento verde.", "Añade el choco al sofrito, rehoga y añade el pimentón. Riega con el vino blanco y deja reducir.", "Pela y chasca las patatas (romperlas en vez de corte limpio) y añádelas a la olla.", "Cubre con agua o fumet, añade los guisantes, y cocina a fuego medio unos 30-40 minutos hasta que el choco esté tierno y el caldo espeso."]}'),
('{"name": "Porra Antequerana", "meal_type": "comida", "price": "economica", "difficulty": "facil", "health": "saludable", "diet_type": "omnivoro", "allergens": ["gluten", "huevo"], "ingredients": [{"name": "Tomates pera muy maduros", "quantity": 1000, "unit": "g"}, {"name": "Pan de hogaza seco (miga)", "quantity": 350, "unit": "g"}, {"name": "Pimiento verde de asar (carnoso)", "quantity": 0.5, "unit": "unidad"}, {"name": "Ajo", "quantity": 1, "unit": "diente"}, {"name": "Aceite de oliva virgen extra", "quantity": 120, "unit": "ml"}, {"name": "Vinagre de Jerez", "quantity": 20, "unit": "ml"}, {"name": "Huevo cocido y jamón (para decorar)", "quantity": 1, "unit": "ración"}], "instructions": ["Retira la corteza al pan y humedece ligeramente la miga con agua.", "Tritura los tomates limpios junto con el pimiento verde y el ajo.", "Pasa la mezcla por un chino para quitar pepitas y pieles.", "Añade la miga de pan escurrida, el vinagre y la sal. Tritura hasta conseguir una pasta muy espesa.", "Sin apagar la batidora, vierte el aceite a hilo para emulsionar la crema.", "Sirve muy fría en plato llano, acompañada de huevo cocido picado y atún o jamón."]}'),
('{"name": "Ensalada César con Pollo Crujiente", "meal_type": "cena", "price": "economica", "difficulty": "intermedia", "health": "no saludable", "diet_type": "omnivoro", "allergens": ["gluten", "lactosa", "huevo"], "ingredients": [{"name": "Lechuga romana", "quantity": 200, "unit": "g"}, {"name": "Pechuga de pollo", "quantity": 150, "unit": "g"}, {"name": "Queso parmesano", "quantity": 30, "unit": "g"}, {"name": "Pan rallado", "quantity": 50, "unit": "g"}, {"name": "Huevo", "quantity": 1, "unit": "unidad"}, {"name": "Salsa César", "quantity": 40, "unit": "ml"}, {"name": "Aceite de oliva", "quantity": 15, "unit": "ml"}], "instructions": ["Limpia y trocea la lechuga romana.", "Salpimentar la pechuga de pollo, pásala por huevo batido y pan rallado.", "Fríe el pollo en una sartén con aceite caliente hasta que esté bien dorado y crujiente. Escurre y corta en tiras.", "Coloca la lechuga en una ensaladera, añade el pollo crujiente caliente y las lascas de queso parmesano.", "Aliña con salsa César y sirve."]}'),
('{"name": "Crema de Calabaza y Jengibre", "meal_type": "cena", "price": "economica", "difficulty": "facil", "health": "saludable", "diet_type": "vegano", "allergens": [], "ingredients": [{"name": "Calabaza limpia", "quantity": 500, "unit": "g"}, {"name": "Puerro", "quantity": 1, "unit": "unidad"}, {"name": "Patata", "quantity": 1, "unit": "unidad"}, {"name": "Jengibre fresco", "quantity": 5, "unit": "g"}, {"name": "Agua o caldo de verduras", "quantity": 500, "unit": "ml"}, {"name": "Aceite de oliva", "quantity": 15, "unit": "ml"}, {"name": "Sal", "quantity": 4, "unit": "g"}], "instructions": ["Limpia y trocea el puerro. Pela la calabaza y la patata en dados medianos.", "En una olla, sofríe el puerro en aceite de oliva unos 5 minutos.", "Añade la calabaza, la patata, el jengibre fresco rallado y rehoga todo junto durante 3 minutos.", "Cubre con el caldo o agua y cuece a fuego medio-bajo durante 25 minutos.", "Tritura bien hasta conseguir una crema muy fina y suave. Corrige de sal."]}'),
('{"name": "Tacos al Pastor", "meal_type": "cena", "price": "economica", "difficulty": "intermedia", "health": "no saludable", "diet_type": "omnivoro", "allergens": [], "ingredients": [{"name": "Carne de cerdo (cabezada)", "quantity": 300, "unit": "g"}, {"name": "Tortillas de maíz", "quantity": 6, "unit": "unidades"}, {"name": "Piña natural", "quantity": 100, "unit": "g"}, {"name": "Cilantro fresco", "quantity": 10, "unit": "g"}, {"name": "Cebolla", "quantity": 0.5, "unit": "unidad"}, {"name": "Pasta de achiote", "quantity": 20, "unit": "g"}, {"name": "Vinagre blanco", "quantity": 20, "unit": "ml"}], "instructions": ["Marina la carne de cerdo cortada en filetes finos con la pasta de achiote disuelta en vinagre y sal durante unas horas.", "Cocina la carne marinada a la plancha o sartén bien caliente y córtala en tiras pequeñas.", "Dora trozos de piña en la misma sartén.", "Calienta las tortillas de maíz en una sartén limpia.", "Monta los tacos colocando la carne adobada, la piña, cebolla picada y abundante cilantro fresco."]}'),
('{"name": "Tortilla de Patatas Española", "meal_type": "cena", "price": "economica", "difficulty": "intermedia", "health": "saludable", "diet_type": "vegetariano", "allergens": ["huevo"], "ingredients": [{"name": "Huevo", "quantity": 5, "unit": "unidades"}, {"name": "Patatas", "quantity": 400, "unit": "g"}, {"name": "Cebolla", "quantity": 150, "unit": "g"}, {"name": "Aceite de oliva", "quantity": 150, "unit": "ml"}, {"name": "Sal", "quantity": 5, "unit": "g"}], "instructions": ["Pela y corta las patatas en láminas finas y pica la cebolla.", "Fríe la cebolla y las patatas en una sartén con abundante aceite de oliva a fuego medio-bajo para que se confiten unos 20 minutos.", "Escurre el aceite sobrante. Bate los huevos en un bol grande con sal y mezcla con las patatas y cebolla escurridas. Deja reposar 5 minutos.", "Cuaja la tortilla en una sartén antiadherente con un par de cucharadas del aceite anterior. Cocina a fuego medio unos 3-4 minutos por lado usando un plato llano para darle la vuelta."]}'),
('{"name": "Salmorejo Cordobés Cremoso", "meal_type": "cena", "price": "economica", "difficulty": "facil", "health": "saludable", "diet_type": "omnivoro", "allergens": ["gluten", "huevo"], "ingredients": [{"name": "Tomates pera maduros", "quantity": 1000, "unit": "g"}, {"name": "Pan de hogaza duro", "quantity": 200, "unit": "g"}, {"name": "Aceite de oliva virgen extra", "quantity": 100, "unit": "ml"}, {"name": "Ajo", "quantity": 1, "unit": "diente"}, {"name": "Sal", "quantity": 5, "unit": "g"}, {"name": "Jamón ibérico en taquitos", "quantity": 50, "unit": "g"}, {"name": "Huevo cocido", "quantity": 1, "unit": "unidad"}], "instructions": ["Lava y trocea los tomates. Tritúralos solos en la batidora hasta obtener un puré líquido.", "Pasa el tomate triturado por un colador fino para quitar semillas y pieles.", "Introduce el pan troceado en el tomate líquido y déjalo reposar 10 minutos para que se ablande.", "Añade el ajo pelado y triturado y una pizca de sal. Tritura todo muy bien hasta obtener una pasta densa.", "Con la batidora en marcha a velocidad media, ve vertiendo el aceite de oliva virgen extra poco a poco para lograr una emulsión espesa y cremosa.", "Sirve en cuencos decorando con el huevo cocido picado y los taquitos de jamón ibérico."]}'),
('{"name": "Pisto Manchego con Huevo", "meal_type": "cena", "price": "economica", "difficulty": "facil", "health": "saludable", "diet_type": "vegetariano", "allergens": ["huevo"], "ingredients": [{"name": "Calabacín", "quantity": 300, "unit": "g"}, {"name": "Berenjena", "quantity": 200, "unit": "g"}, {"name": "Pimiento verde italiano", "quantity": 1, "unit": "unidad"}, {"name": "Pimiento rojo", "quantity": 0.5, "unit": "unidad"}, {"name": "Cebolla", "quantity": 1, "unit": "unidad"}, {"name": "Tomate triturado", "quantity": 400, "unit": "g"}, {"name": "Huevo", "quantity": 2, "unit": "unidades"}, {"name": "Aceite de oliva", "quantity": 30, "unit": "ml"}, {"name": "Sal", "quantity": 5, "unit": "g"}], "instructions": ["Pica finamente la cebolla y los pimientos rojo y verde. Corta el calabacín y la berenjena en dados de 1 cm.", "En una sartén grande con aceite de oliva, sofríe la cebolla y los pimientos con sal hasta que estén blandos.", "Añade la berenjena y el calabacín, y saltea a fuego medio durante 10 minutos.", "Vierte el tomate triturado y deja cocinar todo a fuego lento durante 20 minutos removiendo de vez en cuando.", "Haz dos huecos en el pisto, casca los huevos en ellos, tapa la sartén y deja cuajar a fuego suave unos 4-5 minutos hasta que la clara esté blanca."]}'),
('{"name": "Croquetas de Jamón Ibérico Cremosas", "meal_type": "cena", "price": "economica", "difficulty": "intermedia", "health": "no saludable", "diet_type": "omnivoro", "allergens": ["gluten", "lactosa", "huevo"], "ingredients": [{"name": "Jamón ibérico picado", "quantity": 120, "unit": "g"}, {"name": "Harina de trigo", "quantity": 90, "unit": "g"}, {"name": "Leche entera", "quantity": 800, "unit": "ml"}, {"name": "Mantequilla", "quantity": 90, "unit": "g"}, {"name": "Cebolla mediana", "quantity": 0.5, "unit": "unidad"}, {"name": "Huevo", "quantity": 2, "unit": "unidades"}, {"name": "Pan rallado", "quantity": 150, "unit": "g"}, {"name": "Aceite de oliva para freír", "quantity": 300, "unit": "ml"}, {"name": "Nuez moscada en polvo", "quantity": 1, "unit": "g"}], "instructions": ["Pica la cebolla muy fina y dórala en una sartén con la mantequilla.", "Añade el jamón picado y dale un par de vueltas. Incorpora la harina y remueve 2 minutos.", "Ve vertiendo la leche tibia poco a poco sin dejar de remover con unas varillas.", "Añade nuez moscada y una pizca de sal. Cocina a fuego lento durante 15 minutos removiendo constantemente hasta espesar.", "Vierte la bechamel en una fuente engrasada, cúbrela con film transparente y déjala enfriar unas 4 horas.", "Forma las croquetas, pásalas por huevo batido y después por pan rallado. Fríelas en abundante aceite bien caliente."]}'),
('{"name": "Gambas al Ajillo Clásicas", "meal_type": "cena", "price": "cara", "difficulty": "facil", "health": "saludable", "diet_type": "pescetariano", "allergens": ["marisco"], "ingredients": [{"name": "Gambas peladas frescas", "quantity": 300, "unit": "g"}, {"name": "Dientes de ajo", "quantity": 4, "unit": "unidades"}, {"name": "Guindilla seca", "quantity": 1, "unit": "unidad"}, {"name": "Aceite de oliva virgen extra", "quantity": 60, "unit": "ml"}, {"name": "Perejil fresco picado", "quantity": 5, "unit": "g"}, {"name": "Sal", "quantity": 2, "unit": "g"}], "instructions": ["Limpia las gambas peladas y sécalas bien. Sazónalas con sal.", "Lamina los dientes de ajo y corta la guindilla en rodajas pequeñas.", "En una cazuela de barro con el aceite de oliva, echa los ajos y la guindilla en frío.", "Llévalo al fuego lento. Deja que los ajos comiencen a dorarse despacio.", "Sube el fuego a medio-alto, añade las gambas de golpe y cocínalas moviendo la cazuela unos 2 minutos.", "Espolvorea el perejil picado fresco y retira inmediatamente del fuego. Sirve burbujeando."]}'),
('{"name": "Patatas Bravas Crujientes", "meal_type": "cena", "price": "economica", "difficulty": "intermedia", "health": "no saludable", "diet_type": "vegetariano", "allergens": ["gluten"], "ingredients": [{"name": "Patatas para freír", "quantity": 500, "unit": "g"}, {"name": "Caldo de pollo o verduras", "quantity": 200, "unit": "ml"}, {"name": "Pimentón dulce", "quantity": 5, "unit": "g"}, {"name": "Pimentón picante", "quantity": 5, "unit": "g"}, {"name": "Harina de trigo", "quantity": 15, "unit": "g"}, {"name": "Aceite de oliva", "quantity": 250, "unit": "ml"}, {"name": "Ajo", "quantity": 1, "unit": "diente"}, {"name": "Sal", "quantity": 3, "unit": "g"}], "instructions": ["Para la salsa brava: en un cazo calienta 20 ml de aceite, añade el diente de ajo picado y dóralo.", "Añade la harina, el pimentón dulce y picante, remueve rápidamente durante 1 minuto.", "Ve vertiendo el caldo caliente poco a poco y remueve con varillas hasta que espese y hierva unos 10 minutos. Tritura y cuela.", "Pela las patatas y trocéalas cortándolas en dados irregulares. Lava bien y sécalas.", "Confitar las patatas friéndolas a fuego medio unos 10 minutos. Retíralas.", "Sube el fuego al máximo y fríelas de nuevo 2 minutos para que queden crujientes. Añade sal y salsa brava."]}'),
('{"name": "Merluza a la Vasca con Almejas", "meal_type": "cena", "price": "cara", "difficulty": "intermedia", "health": "saludable", "diet_type": "pescetariano", "allergens": ["pescado", "marisco", "gluten"], "ingredients": [{"name": "Lomos de merluza", "quantity": 400, "unit": "g"}, {"name": "Almejas frescas", "quantity": 150, "unit": "g"}, {"name": "Caldo de pescado", "quantity": 250, "unit": "ml"}, {"name": "Vino blanco", "quantity": 50, "unit": "ml"}, {"name": "Harina de trigo", "quantity": 15, "unit": "g"}, {"name": "Guisantes cocidos", "quantity": 50, "unit": "g"}, {"name": "Yemas de espárrago blanco", "quantity": 4, "unit": "unidades"}, {"name": "Dientes de ajo", "quantity": 2, "unit": "dientes"}, {"name": "Perejil fresco picado", "quantity": 10, "unit": "g"}, {"name": "Aceite de oliva", "quantity": 30, "unit": "ml"}, {"name": "Sal", "quantity": 3, "unit": "g"}], "instructions": ["Pon las almejas en remojo en agua fría con sal una hora antes.", "Pica finamente los ajos y sofríelos en una cazuela ancha con aceite sin que cojan color.", "Sazona la merluza, pásala ligeramente por harina e introdúcela en la cazuela.", "Vierte el vino blanco y deja reducir el alcohol a fuego medio 2 minutos.", "Añade el caldo de pescado caliente y el perejil. Cocina a fuego lento moviendo la cazuela para ligar la salsa.", "Añade las almejas limpias, los guisantes y las yemas de espárragos. Tapa y cocina 3-4 minutos hasta que las almejas se abran."]}'),
('{"name": "Pimientos del Piquillo Rellenos de Bacalao", "meal_type": "cena", "price": "economica", "difficulty": "intermedia", "health": "saludable", "diet_type": "pescetariano", "allergens": ["pescado", "gluten", "lactosa"], "ingredients": [{"name": "Pimientos del piquillo enteros", "quantity": 12, "unit": "unidades"}, {"name": "Bacalao desalado desmigado", "quantity": 250, "unit": "g"}, {"name": "Cebolla grande", "quantity": 1, "unit": "unidad"}, {"name": "Harina de trigo", "quantity": 40, "unit": "g"}, {"name": "Leche entera", "quantity": 350, "unit": "ml"}, {"name": "Nata líquida para cocinar", "quantity": 150, "unit": "ml"}, {"name": "Ajo", "quantity": 2, "unit": "dientes"}, {"name": "Aceite de oliva", "quantity": 30, "unit": "ml"}, {"name": "Sal", "quantity": 3, "unit": "g"}], "instructions": ["Para el relleno: pica media cebolla y un ajo. Sofríelos, añade el bacalao y saltea 3 minutos.", "Añade la harina, revuelve bien, y ve incorporando la leche caliente poco a poco hasta obtener una bechamel muy espesa y suave.", "Rellena con cuidado los pimientos del piquillo con la bechamel fría.", "Para la salsa: sofríe la otra media cebolla y el otro ajo. Añade dos pimientos del piquillo rotos, la nata, sal y cocina 5 minutos.", "Tritura la salsa muy fina, pásala a una cazuela, coloca los pimientos rellenos encima y caliéntalos a fuego suave 10 minutos."]}'),
('{"name": "Sopa Castellana (Sopa de Ajo)", "meal_type": "cena", "price": "economica", "difficulty": "facil", "health": "saludable", "diet_type": "omnivoro", "allergens": ["gluten", "huevo"], "ingredients": [{"name": "Pan duro", "quantity": 100, "unit": "g"}, {"name": "Ajos", "quantity": 6, "unit": "dientes"}, {"name": "Jamón serrano en tacos", "quantity": 50, "unit": "g"}, {"name": "Pimentón dulce", "quantity": 10, "unit": "g"}, {"name": "Huevos", "quantity": 2, "unit": "unidades"}, {"name": "Caldo de pollo o agua", "quantity": 1, "unit": "litro"}, {"name": "Aceite de oliva", "quantity": 40, "unit": "ml"}], "instructions": ["Lamina los ajos y fríelos suavemente en una olla con aceite de oliva hasta dorarlos.", "Añade los taquitos de jamón y dales una vuelta.", "Corta el pan duro en rebanadas finas, añádelo a la olla y tuesta la miga.", "Aparta del fuego, añade el pimentón y remueve para que no se queme. Vierte el caldo caliente.", "Cuece 15 minutos a fuego suave. Casca los huevos enteros en la sopa caliente para que se escalfen antes de servir."]}'),
('{"name": "Huevos Rotos con Jamón", "meal_type": "cena", "price": "economica", "difficulty": "facil", "health": "no saludable", "diet_type": "omnivoro", "allergens": ["huevo"], "ingredients": [{"name": "Patatas", "quantity": 400, "unit": "g"}, {"name": "Huevos", "quantity": 3, "unit": "unidades"}, {"name": "Jamón ibérico en lonchas", "quantity": 100, "unit": "g"}, {"name": "Aceite de oliva para freír", "quantity": 300, "unit": "ml"}, {"name": "Sal", "quantity": 3, "unit": "g"}], "instructions": ["Pela y corta las patatas en bastones. Fríelas en abundante aceite de oliva caliente hasta que estén doradas y tiernas. Escúrrelas y sálalas.", "En una sartén aparte con un poco del mismo aceite, fríe los huevos dejando la yema líquida.", "Coloca las patatas calientes en una fuente, pon los huevos fritos encima.", "Rompe los huevos (las yemas) sobre las patatas con ayuda de un cuchillo y tenedor.", "Cubre rápidamente con las lonchas de jamón ibérico para que el calor residual funda la grasa del jamón."]}'),
('{"name": "Berenjenas Fritas con Miel de Caña", "meal_type": "cena", "price": "economica", "difficulty": "facil", "health": "no saludable", "diet_type": "vegetariano", "allergens": ["gluten"], "ingredients": [{"name": "Berenjenas", "quantity": 2, "unit": "unidades"}, {"name": "Harina de fritura o garbanzo", "quantity": 100, "unit": "g"}, {"name": "Miel de caña (melaza)", "quantity": 50, "unit": "ml"}, {"name": "Aceite de oliva para freír", "quantity": 300, "unit": "ml"}, {"name": "Sal", "quantity": 5, "unit": "g"}, {"name": "Leche o cerveza (para remojo)", "quantity": 200, "unit": "ml"}], "instructions": ["Corta las berenjenas en bastones gruesos o rodajas de 1 cm.", "Ponlas en remojo en leche o cerveza durante 30 minutos para quitar el amargor y que queden crujientes.", "Escurre, seca bien con papel absorbente y ponles sal.", "Pasa las berenjenas por harina sacudiendo muy bien el exceso (puedes usar un colador).", "Fríe en aceite muy caliente por tandas. Escurre en papel y sirve inmediatamente con un hilo fino de miel de caña por encima."]}'),
('{"name": "Zarangollo Murciano", "meal_type": "cena", "price": "economica", "difficulty": "facil", "health": "saludable", "diet_type": "vegetariano", "allergens": ["huevo"], "ingredients": [{"name": "Calabacines", "quantity": 2, "unit": "unidades"}, {"name": "Cebollas dulces", "quantity": 2, "unit": "unidades"}, {"name": "Huevos", "quantity": 4, "unit": "unidades"}, {"name": "Aceite de oliva", "quantity": 30, "unit": "ml"}, {"name": "Sal", "quantity": 3, "unit": "g"}], "instructions": ["Pela y corta la cebolla en juliana fina. Corta el calabacín (con o sin piel) en rodajas finas.", "En una sartén con aceite, pocha la cebolla a fuego muy lento hasta que esté transparente.", "Añade el calabacín, sala y deja pochar todo junto tapado durante unos 30-40 minutos, removiendo de vez en cuando, hasta que esté muy tierno y pierda el agua.", "Escurre el exceso de aceite y agua si lo hubiera.", "Añade los huevos directamente a la sartén y revuelve a fuego mínimo hasta que cuajen ligeramente y quede muy jugoso."]}'),
('{"name": "Huevos a la Flamenca", "meal_type": "cena", "price": "economica", "difficulty": "facil", "health": "saludable", "diet_type": "omnivoro", "allergens": ["huevo"], "ingredients": [{"name": "Huevos", "quantity": 2, "unit": "unidades"}, {"name": "Tomate frito casero", "quantity": 200, "unit": "g"}, {"name": "Guisantes cocidos", "quantity": 50, "unit": "g"}, {"name": "Jamón serrano en tacos", "quantity": 30, "unit": "g"}, {"name": "Chorizo en rodajas", "quantity": 30, "unit": "g"}, {"name": "Patatas medianas", "quantity": 1, "unit": "unidad"}], "instructions": ["Pela y corta las patatas en dados y fríelas. Escurre y reparte en el fondo de dos cazuelas de barro individuales.", "Añade los guisantes y cúbrelo todo con el tomate frito caliente.", "Casca un huevo encima de cada cazuela de barro.", "Reparte los tacos de jamón y rodajas de chorizo alrededor de la clara del huevo.", "Hornea a 200°C durante unos 8-10 minutos, lo justo para que cuaje la clara pero la yema quede líquida."]}'),
('{"name": "Risotto de Setas y Parmesano", "meal_type": "cena", "price": "cara", "difficulty": "intermedia", "health": "saludable", "diet_type": "vegetariano", "allergens": ["lactosa"], "ingredients": [{"name": "Arroz Arborio o Carnaroli", "quantity": 300, "unit": "g"}, {"name": "Setas variadas (o champiñones)", "quantity": 250, "unit": "g"}, {"name": "Caldo de verduras caliente", "quantity": 1, "unit": "litro"}, {"name": "Cebolla", "quantity": 0.5, "unit": "unidad"}, {"name": "Vino blanco", "quantity": 100, "unit": "ml"}, {"name": "Queso Parmesano rallado", "quantity": 80, "unit": "g"}, {"name": "Mantequilla", "quantity": 40, "unit": "g"}], "instructions": ["Sofríe la cebolla finamente picada en un poco de mantequilla. Añade las setas troceadas y saltea.", "Incorpora el arroz y tuéstalo un par de minutos. Vierte el vino blanco y deja evaporar.", "Añade el caldo caliente cazo a cazo, sin dejar de remover, esperando a que se absorba antes de echar el siguiente.", "Tras 18 minutos, retira del fuego.", "Añade la mantequilla restante y el queso parmesano. Remueve enérgicamente (mantecar) y sirve al momento."]}'),
('{"name": "Lasaña de Carne a la Boloñesa", "meal_type": "comida", "price": "economica", "difficulty": "intermedia", "health": "no saludable", "diet_type": "omnivoro", "allergens": ["gluten", "lactosa", "huevo"], "ingredients": [{"name": "Placas de lasaña", "quantity": 12, "unit": "unidades"}, {"name": "Carne picada mixta", "quantity": 500, "unit": "g"}, {"name": "Tomate triturado", "quantity": 400, "unit": "g"}, {"name": "Cebolla", "quantity": 1, "unit": "unidad"}, {"name": "Zanahoria", "quantity": 1, "unit": "unidad"}, {"name": "Bechamel", "quantity": 500, "unit": "ml"}, {"name": "Queso rallado para gratinar", "quantity": 100, "unit": "g"}], "instructions": ["Prepara un sofrito con la cebolla y la zanahoria muy picadas.", "Añade la carne picada y cocínala hasta que cambie de color. Vierte el tomate triturado y deja reducir 20 minutos.", "Monta la lasaña alternando capas de pasta, salsa boloñesa y bechamel.", "Termina con una capa de bechamel y queso rallado.", "Hornea a 200°C durante 20 minutos hasta que el queso esté gratinado."]}'),
('{"name": "Pollo Tikka Masala", "meal_type": "comida", "price": "economica", "difficulty": "intermedia", "health": "saludable", "diet_type": "omnivoro", "allergens": ["lactosa"], "ingredients": [{"name": "Pechuga de pollo", "quantity": 500, "unit": "g"}, {"name": "Yogur natural", "quantity": 125, "unit": "g"}, {"name": "Garam Masala", "quantity": 15, "unit": "g"}, {"name": "Cúrcuma", "quantity": 5, "unit": "g"}, {"name": "Tomate triturado", "quantity": 400, "unit": "g"}, {"name": "Leche de coco (o nata)", "quantity": 200, "unit": "ml"}, {"name": "Ajo y jengibre rallado", "quantity": 15, "unit": "g"}, {"name": "Arroz basmati (para acompañar)", "quantity": 200, "unit": "g"}], "instructions": ["Marina el pollo troceado con el yogur, jengibre, ajo y la mitad de las especias durante 1 hora.", "Dora el pollo en una sartén a fuego fuerte y retíralo.", "En la misma sartén, sofríe cebolla, añade el resto de especias, el tomate triturado y deja cocinar 15 minutos.", "Vierte la leche de coco, vuelve a meter el pollo y cocina todo a fuego lento 10 minutos más.", "Sirve caliente acompañado de arroz basmati cocido."]}'),
('{"name": "Curry Vegano de Garbanzos y Coco", "meal_type": "cena", "price": "economica", "difficulty": "facil", "health": "saludable", "diet_type": "vegano", "allergens": [], "ingredients": [{"name": "Garbanzos cocidos", "quantity": 400, "unit": "g"}, {"name": "Leche de coco", "quantity": 400, "unit": "ml"}, {"name": "Espinacas frescas", "quantity": 100, "unit": "g"}, {"name": "Cebolla", "quantity": 1, "unit": "unidad"}, {"name": "Pasta de curry amarillo", "quantity": 30, "unit": "g"}, {"name": "Tomate troceado", "quantity": 200, "unit": "g"}, {"name": "Aceite de oliva", "quantity": 15, "unit": "ml"}], "instructions": ["Pica la cebolla y sofríela en una olla con aceite.", "Añade la pasta de curry y remueve un minuto para que suelte aroma.", "Incorpora el tomate, los garbanzos escurridos y la leche de coco. Deja hervir a fuego suave 15 minutos.", "Apaga el fuego, añade las espinacas frescas y remueve para que se marchiten con el calor residual.", "Sirve en boles acompañado de pan naan o arroz."]}'),
('{"name": "Pad Thai de Gambas", "meal_type": "comida", "price": "cara", "difficulty": "intermedia", "health": "saludable", "diet_type": "pescetariano", "allergens": ["marisco", "huevo", "frutos secos", "soja"], "ingredients": [{"name": "Fideos de arroz", "quantity": 200, "unit": "g"}, {"name": "Gambas peladas", "quantity": 200, "unit": "g"}, {"name": "Huevos", "quantity": 2, "unit": "unidades"}, {"name": "Brotes de soja", "quantity": 100, "unit": "g"}, {"name": "Cacahuetes tostados", "quantity": 30, "unit": "g"}, {"name": "Salsa de soja", "quantity": 30, "unit": "ml"}, {"name": "Salsa de pescado", "quantity": 15, "unit": "ml"}, {"name": "Pasta de tamarindo", "quantity": 15, "unit": "g"}], "instructions": ["Hidrata los fideos de arroz en agua tibia unos 15 minutos.", "En un wok con un poco de aceite, saltea las gambas y retíralas.", "Casca los huevos en el wok y haz un revuelto rápido.", "Añade los fideos escurridos, la salsa de soja, la salsa de pescado y el tamarindo. Saltea a fuego fuerte.", "Incorpora los brotes de soja y las gambas. Sirve con cacahuetes picados y un gajo de lima."]}'),
('{"name": "Hummus Tradicional con Pan de Pita", "meal_type": "cena", "price": "economica", "difficulty": "facil", "health": "saludable", "diet_type": "vegano", "allergens": ["sesamo", "gluten"], "ingredients": [{"name": "Garbanzos cocidos", "quantity": 400, "unit": "g"}, {"name": "Tahini (pasta de sésamo)", "quantity": 30, "unit": "g"}, {"name": "Zumo de limón", "quantity": 30, "unit": "ml"}, {"name": "Ajo", "quantity": 1, "unit": "diente"}, {"name": "Aceite de oliva virgen extra", "quantity": 30, "unit": "ml"}, {"name": "Comino en polvo", "quantity": 2, "unit": "g"}, {"name": "Pan de pita", "quantity": 4, "unit": "unidades"}], "instructions": ["Lava y escurre bien los garbanzos.", "Ponlos en la batidora junto con el ajo, tahini, comino, sal y zumo de limón.", "Tritura hasta obtener una pasta. Añade agua fría poco a poco si queda muy espeso.", "Sirve en un plato llano, haz un surco con la cuchara y echa un buen chorro de aceite de oliva y pimentón.", "Acompaña con pan de pita tostado o bastones de zanahoria."]}'),
('{"name": "Falafel Casero con Salsa de Yogur", "meal_type": "cena", "price": "economica", "difficulty": "intermedia", "health": "saludable", "diet_type": "vegetariano", "allergens": ["lactosa"], "ingredients": [{"name": "Garbanzos secos (remojados 24h)", "quantity": 300, "unit": "g"}, {"name": "Cebolla", "quantity": 0.5, "unit": "unidad"}, {"name": "Ajo", "quantity": 2, "unit": "dientes"}, {"name": "Cilantro y perejil fresco", "quantity": 20, "unit": "g"}, {"name": "Comino en polvo", "quantity": 5, "unit": "g"}, {"name": "Aceite para freír", "quantity": 300, "unit": "ml"}, {"name": "Yogur griego", "quantity": 1, "unit": "unidad"}], "instructions": ["Tritura los garbanzos (escurridos y SIN cocer) en una picadora junto con la cebolla, el ajo y las hierbas frescas hasta hacer una pasta arenosa.", "Añade comino, sal y pimienta. Mezcla bien y deja reposar la masa en la nevera 1 hora.", "Forma pequeñas bolas o hamburguesitas con las manos.", "Fríe el falafel en abundante aceite caliente hasta que estén muy tostados y crujientes por fuera.", "Para la salsa, mezcla el yogur griego con unas gotas de limón, sal y menta picada."]}'),
('{"name": "Enchiladas Verdes de Pollo", "meal_type": "comida", "price": "economica", "difficulty": "intermedia", "health": "no saludable", "diet_type": "omnivoro", "allergens": ["lactosa"], "ingredients": [{"name": "Tortillas de maíz", "quantity": 8, "unit": "unidades"}, {"name": "Pechuga de pollo cocida y desmechada", "quantity": 300, "unit": "g"}, {"name": "Salsa verde mexicana (tomatillo)", "quantity": 400, "unit": "g"}, {"name": "Queso rallado", "quantity": 100, "unit": "g"}, {"name": "Nata agria o crema", "quantity": 50, "unit": "ml"}, {"name": "Cebolla morada", "quantity": 0.5, "unit": "unidad"}], "instructions": ["Pasa las tortillas de maíz ligeramente por una sartén caliente para que no se rompan.", "Rellena cada tortilla con el pollo desmechado y enróllalas en forma de tubo.", "Colócalas en una fuente de horno, báñalas con abundante salsa verde y espolvorea el queso rallado.", "Gratina en el horno 10 minutos hasta que el queso se funda.", "Sirve con hilos de crema agria y cebolla morada cortada muy fina por encima."]}'),
('{"name": "Ceviche Peruano de Corvina", "meal_type": "cena", "price": "cara", "difficulty": "facil", "health": "saludable", "diet_type": "pescetariano", "allergens": ["pescado"], "ingredients": [{"name": "Corvina fresca y limpia", "quantity": 400, "unit": "g"}, {"name": "Limas", "quantity": 6, "unit": "unidades"}, {"name": "Cebolla morada", "quantity": 1, "unit": "unidad"}, {"name": "Cilantro fresco", "quantity": 10, "unit": "g"}, {"name": "Ají limo o chile fresco", "quantity": 1, "unit": "unidad"}, {"name": "Maíz tostado o choclo", "quantity": 50, "unit": "g"}, {"name": "Sal", "quantity": 5, "unit": "g"}], "instructions": ["Corta el pescado en cubos de 1,5 cm. Colócalo en un bol de cristal frotado previamente con un trozo de ají.", "Añade sal generosa y mezcla bien el pescado.", "Corta la cebolla morada en pluma muy fina y lávala con agua fría.", "Exprime el zumo de las limas directamente sobre el pescado (sin exprimir hasta el final para que no amargue).", "Añade el cilantro picado, el ají picado sin pepitas y la cebolla. Mezcla y deja reposar 3-5 minutos máximo.", "Sirve inmediatamente acompañado de maíz tostado."]}'),
('{"name": "Hamburguesa Clásica Americana", "meal_type": "cena", "price": "economica", "difficulty": "facil", "health": "no saludable", "diet_type": "omnivoro", "allergens": ["gluten", "lactosa", "sesamo"], "ingredients": [{"name": "Carne picada de ternera (20% grasa)", "quantity": 300, "unit": "g"}, {"name": "Panes de hamburguesa con sésamo", "quantity": 2, "unit": "unidades"}, {"name": "Queso Cheddar", "quantity": 2, "unit": "lonchas"}, {"name": "Lechuga iceberg", "quantity": 2, "unit": "hojas"}, {"name": "Tomate", "quantity": 1, "unit": "unidad"}, {"name": "Bacon ahumado", "quantity": 4, "unit": "lonchas"}, {"name": "Salsa barbacoa o kétchup", "quantity": 20, "unit": "ml"}], "instructions": ["Forma dos discos con la carne picada y haz un pequeño hoyo en el centro para que no se encojan.", "Tuesta la cara interna de los panes de hamburguesa en una sartén con un poco de mantequilla.", "Haz el bacon a la plancha hasta que esté crujiente.", "Salpimienta la carne y hazla a la plancha a fuego fuerte (unos 3 min por lado). En el último minuto, pon el queso encima para que se funda.", "Monta la hamburguesa: pan, salsa, lechuga, tomate, carne con queso, bacon y pan superior."]}'),
('{"name": "Quiche Lorraine Clásica", "meal_type": "comida", "price": "economica", "difficulty": "intermedia", "health": "no saludable", "diet_type": "omnivoro", "allergens": ["gluten", "lactosa", "huevo"], "ingredients": [{"name": "Masa quebrada", "quantity": 1, "unit": "lámina"}, {"name": "Bacon o panceta", "quantity": 150, "unit": "g"}, {"name": "Nata líquida", "quantity": 200, "unit": "ml"}, {"name": "Huevos", "quantity": 3, "unit": "unidades"}, {"name": "Queso Gruyère rallado", "quantity": 100, "unit": "g"}, {"name": "Nuez moscada", "quantity": 1, "unit": "g"}, {"name": "Pimienta negra", "quantity": 1, "unit": "g"}], "instructions": ["Desenrolla la masa quebrada sobre un molde de tarta, pincha el fondo con un tenedor y hornea en blanco (con peso encima) 10 min a 180°C.", "Saltea el bacon en una sartén sin aceite hasta que dore. Escurre la grasa.", "En un bol, bate los huevos con la nata, sal, pimienta y nuez moscada.", "Reparte el bacon y el queso rallado sobre la base de masa precocida.", "Vierte la mezcla de nata y huevos. Hornea a 180°C durante 25-30 minutos hasta que cuaje y dore."]}'),
('{"name": "Empanadas Argentinas de Carne", "meal_type": "comida", "price": "economica", "difficulty": "intermedia", "health": "no saludable", "diet_type": "omnivoro", "allergens": ["gluten", "huevo"], "ingredients": [{"name": "Tapas de empanada (masa para horno)", "quantity": 12, "unit": "unidades"}, {"name": "Carne picada de ternera", "quantity": 300, "unit": "g"}, {"name": "Cebolla", "quantity": 2, "unit": "unidades"}, {"name": "Huevo duro", "quantity": 2, "unit": "unidades"}, {"name": "Aceitunas verdes", "quantity": 50, "unit": "g"}, {"name": "Comino molido", "quantity": 3, "unit": "g"}, {"name": "Pimentón dulce", "quantity": 3, "unit": "g"}], "instructions": ["Pocha mucha cebolla finamente picada a fuego lento. Cuando esté transparente, añade la carne y sube el fuego.", "Sazona con sal, pimienta, comino y pimentón. Apaga el fuego cuando la carne cambie de color (sin que se seque).", "Añade a la carne los huevos duros picados y las aceitunas troceadas. Deja enfriar la mezcla por completo.", "Pon una cucharada de relleno en el centro de cada tapa, cierra humedeciendo los bordes y haz el repulgue (dobladillo).", "Pinta con huevo batido y hornea a 200°C unos 15-20 minutos hasta que estén bien doradas."]}'),
('{"name": "Arroz con Leche Tradicional (Postre)", "meal_type": "cena", "price": "economica", "difficulty": "facil", "health": "no saludable", "diet_type": "vegetariano", "allergens": ["lactosa"], "ingredients": [{"name": "Arroz redondo", "quantity": 150, "unit": "g"}, {"name": "Leche entera", "quantity": 1, "unit": "litro"}, {"name": "Azúcar", "quantity": 120, "unit": "g"}, {"name": "Rama de canela", "quantity": 1, "unit": "unidad"}, {"name": "Piel de limón", "quantity": 1, "unit": "unidad"}, {"name": "Canela en polvo", "quantity": 5, "unit": "g"}], "instructions": ["Pon la leche en una olla con la rama de canela, la piel de limón limpia y el azúcar. Llévalo a ebullición suave.", "Lava un poco el arroz bajo el grifo para quitar el exceso de almidón.", "Cuando la leche empiece a hervir, añade el arroz y baja el fuego al mínimo.", "Cocina durante unos 40-50 minutos removiendo frecuentemente, sobre todo al final, para que quede cremoso y no se pegue.", "Retira la canela y el limón, vierte en cuencos individuales y espolvorea canela en polvo por encima antes de enfriar."]}'),
('{"name": "Crema Catalana Quemada (Postre)", "meal_type": "cena", "price": "economica", "difficulty": "intermedia", "health": "no saludable", "diet_type": "vegetariano", "allergens": ["lactosa", "huevo"], "ingredients": [{"name": "Leche entera", "quantity": 750, "unit": "ml"}, {"name": "Yemas de huevo", "quantity": 6, "unit": "unidades"}, {"name": "Azúcar", "quantity": 150, "unit": "g"}, {"name": "Maicena (Almidón de maíz)", "quantity": 30, "unit": "g"}, {"name": "Piel de naranja y limón", "quantity": 1, "unit": "unidad"}, {"name": "Rama de canela", "quantity": 1, "unit": "unidad"}], "instructions": ["Infusiona casi toda la leche en un cazo con las pieles de los cítricos y la canela. Reserva un vasito de leche fría.", "En un bol, mezcla las yemas con 100g de azúcar y la maicena disuelta en el vaso de leche fría.", "Cuela la leche infusionada caliente sobre la mezcla de yemas sin dejar de batir.", "Devuelve todo al cazo a fuego lento y remueve constantemente con varillas hasta que espese (sin que llegue a hervir).", "Reparte en cazuelitas de barro y deja enfriar. Justo antes de servir, espolvorea el azúcar restante y quémalo con un soplete."]}'),
('{"name": "Flan de Huevo de la Abuela (Postre)", "meal_type": "comida", "price": "economica", "difficulty": "facil", "health": "no saludable", "diet_type": "vegetariano", "allergens": ["lactosa", "huevo"], "ingredients": [{"name": "Leche entera", "quantity": 500, "unit": "ml"}, {"name": "Huevos", "quantity": 4, "unit": "unidades"}, {"name": "Azúcar", "quantity": 100, "unit": "g"}, {"name": "Esencia de vainilla", "quantity": 5, "unit": "ml"}, {"name": "Azúcar para el caramelo", "quantity": 60, "unit": "g"}], "instructions": ["Prepara el caramelo fundiendo los 60g de azúcar en un cazo a fuego lento hasta que se tueste. Vierte el caramelo en el fondo de las flaneras.", "Precalienta el horno a 170°C y prepara una bandeja profunda con agua para baño maría.", "En un bol, bate los huevos con los 100g de azúcar y la vainilla sin hacer demasiada espuma.", "Añade la leche tibia y mezcla bien. Cuela la mezcla para evitar grumos y viértela en las flaneras.", "Hornea al baño maría durante unos 45 minutos. Deja enfriar a temperatura ambiente y luego en la nevera antes de desmoldar."]}'),
('{"name": "Tarta de Queso de la Viña (Postre)", "meal_type": "cena", "price": "cara", "difficulty": "facil", "health": "no saludable", "diet_type": "vegetariano", "allergens": ["lactosa", "huevo"], "ingredients": [{"name": "Queso crema (tipo Philadelphia)", "quantity": 600, "unit": "g"}, {"name": "Nata líquida para montar (35% MG)", "quantity": 400, "unit": "ml"}, {"name": "Huevos", "quantity": 4, "unit": "unidades"}, {"name": "Azúcar", "quantity": 200, "unit": "g"}, {"name": "Harina de trigo", "quantity": 15, "unit": "g"}], "instructions": ["Precalienta el horno a 200°C con calor arriba y abajo.", "En un bol grande, bate el queso crema junto con el azúcar hasta que quede suave.", "Añade los huevos uno a uno mezclando bien. Incorpora la harina tamizada y por último la nata líquida.", "Forra un molde redondo (20-22 cm) con papel de horno humedecido y arrugado para que se adapte.", "Vierte la mezcla y hornea 40 minutos. La tarta debe quedar muy tostada por arriba pero \"bailar\" en el centro al moverla. Deja enfriar completamente en el molde."]}'),
('{"name": "Tarta de Santiago (Postre)", "meal_type": "comida", "price": "cara", "difficulty": "facil", "health": "no saludable", "diet_type": "vegetariano", "allergens": ["huevo", "frutos secos"], "ingredients": [{"name": "Almendra molida cruda", "quantity": 250, "unit": "g"}, {"name": "Azúcar", "quantity": 250, "unit": "g"}, {"name": "Huevos", "quantity": 5, "unit": "unidades"}, {"name": "Ralladura de limón", "quantity": 1, "unit": "unidad"}, {"name": "Canela en polvo", "quantity": 2, "unit": "g"}, {"name": "Azúcar glas (para decorar)", "quantity": 30, "unit": "g"}], "instructions": ["Precalienta el horno a 180°C y engrasa un molde redondo desmontable.", "En un bol grande, mezcla el azúcar, la almendra molida, la ralladura de limón y la canela.", "Añade los huevos uno a uno, mezclando suavemente con una espátula o tenedor, sin batir en exceso para no dar aire a la masa.", "Vierte la masa en el molde y hornea unos 30-35 minutos hasta que la superficie esté dorada y firme.", "Deja enfriar, coloca una plantilla con la Cruz de Santiago en el centro y espolvorea generosamente con azúcar glas."]}'),
('{"name": "Natillas Caseras con Galleta (Postre)", "meal_type": "comida", "price": "economica", "difficulty": "facil", "health": "no saludable", "diet_type": "vegetariano", "allergens": ["lactosa", "huevo", "gluten"], "ingredients": [{"name": "Leche entera", "quantity": 600, "unit": "ml"}, {"name": "Yemas de huevo", "quantity": 4, "unit": "unidades"}, {"name": "Azúcar", "quantity": 100, "unit": "g"}, {"name": "Maicena", "quantity": 15, "unit": "g"}, {"name": "Vaina de vainilla", "quantity": 1, "unit": "unidad"}, {"name": "Galletas tipo María", "quantity": 4, "unit": "unidades"}, {"name": "Canela en polvo", "quantity": 5, "unit": "g"}], "instructions": ["Abre la vaina de vainilla y extrae las semillas. Calienta en un cazo la leche (reserva un vasito) con la vaina y semillas. Retira antes de hervir.", "En un bol, mezcla las yemas con el azúcar y la maicena disuelta en la leche fría reservada.", "Vierte la leche caliente (sin la vaina) sobre las yemas sin parar de remover.", "Vuelve a echar la mezcla al cazo y pon a fuego lento removiendo hasta que espese y cubra el dorso de la cuchara (no debe hervir).", "Reparte en cazuelas, pon una galleta María encima de cada una y espolvorea canela al enfriar."]}'),
('{"name": "Quesada Pasiega (Postre)", "meal_type": "comida", "price": "economica", "difficulty": "facil", "health": "no saludable", "diet_type": "vegetariano", "allergens": ["lactosa", "huevo", "gluten"], "ingredients": [{"name": "Queso fresco de vaca o requesón", "quantity": 500, "unit": "g"}, {"name": "Huevos", "quantity": 3, "unit": "unidades"}, {"name": "Azúcar", "quantity": 200, "unit": "g"}, {"name": "Harina de trigo", "quantity": 100, "unit": "g"}, {"name": "Mantequilla derretida", "quantity": 80, "unit": "g"}, {"name": "Ralladura de limón", "quantity": 1, "unit": "unidad"}, {"name": "Canela en polvo", "quantity": 5, "unit": "g"}], "instructions": ["Precalienta el horno a 180°C y engrasa un molde bajo con un poco de mantequilla.", "En un bol grande, desmenuza el queso fresco con un tenedor (no debe quedar como una crema lisa, los grumos son típicos de la quesada).", "Añade los huevos batidos, el azúcar, la mantequilla derretida templada, la ralladura de limón y la canela. Mezcla bien.", "Incorpora la harina tamizada y mezcla suavemente hasta integrar.", "Vierte en el molde y hornea unos 35-40 minutos hasta que la superficie esté dorada. Al enfriar bajará su volumen."]}'),
('{"name": "Pan de Calatrava (Postre)", "meal_type": "cena", "price": "economica", "difficulty": "facil", "health": "no saludable", "diet_type": "vegetariano", "allergens": ["lactosa", "huevo", "gluten"], "ingredients": [{"name": "Leche entera", "quantity": 500, "unit": "ml"}, {"name": "Huevos", "quantity": 4, "unit": "unidades"}, {"name": "Azúcar", "quantity": 150, "unit": "g"}, {"name": "Magdalenas, bizcochos o pan duro", "quantity": 150, "unit": "g"}, {"name": "Caramelo líquido", "quantity": 50, "unit": "ml"}], "instructions": ["Cubre el fondo y un poco las paredes de un molde rectangular tipo plum-cake con el caramelo líquido.", "Desmiga los bizcochos, magdalenas o pan del día anterior y repártelos por el fondo del molde caramelizado.", "Bate los huevos con el azúcar y la leche hasta obtener una mezcla homogénea (como la de un flan).", "Vierte la mezcla de huevo despacio sobre los bizcochos para que se empapen bien.", "Hornea al baño maría a 180°C durante unos 45-50 minutos. Comprueba con un palillo que esté cuajado, deja enfriar y desmolda."]}'),
('{"name": "Tiramisú Clásico (Postre)", "meal_type": "cena", "price": "economica", "difficulty": "facil", "health": "no saludable", "diet_type": "vegetariano", "allergens": ["gluten", "lactosa", "huevo"], "ingredients": [{"name": "Queso Mascarpone", "quantity": 250, "unit": "g"}, {"name": "Huevos", "quantity": 3, "unit": "unidades"}, {"name": "Azúcar", "quantity": 75, "unit": "g"}, {"name": "Bizcochos de soletilla", "quantity": 200, "unit": "g"}, {"name": "Café expreso frío", "quantity": 200, "unit": "ml"}, {"name": "Licor Amaretto (opcional)", "quantity": 20, "unit": "ml"}, {"name": "Cacao puro en polvo", "quantity": 15, "unit": "g"}], "instructions": ["Separa las yemas de las claras. Bate las yemas con la mitad del azúcar hasta que blanqueen.", "Añade el queso mascarpone a las yemas y mezcla suavemente.", "Monta las claras a punto de nieve con el resto del azúcar e incorpóralas a la mezcla anterior con movimientos envolventes.", "Mezcla el café frío con el licor. Baña ligeramente los bizcochos en el café y pon una capa en el fondo de un molde.", "Cubre con la mitad de la crema, pon otra capa de bizcochos y termina con el resto de la crema. Refrigera 4 horas y espolvorea cacao antes de servir."]}'),
('{"name": "Brownie de Chocolate y Nueces (Postre)", "meal_type": "cena", "price": "economica", "difficulty": "facil", "health": "no saludable", "diet_type": "vegetariano", "allergens": ["gluten", "lactosa", "huevo", "frutos secos"], "ingredients": [{"name": "Chocolate para postres (70%)", "quantity": 200, "unit": "g"}, {"name": "Mantequilla", "quantity": 110, "unit": "g"}, {"name": "Huevos", "quantity": 3, "unit": "unidades"}, {"name": "Azúcar", "quantity": 100, "unit": "g"}, {"name": "Harina de trigo", "quantity": 80, "unit": "g"}, {"name": "Nueces peladas", "quantity": 50, "unit": "g"}], "instructions": ["Precalienta el horno a 180°C. Forra un molde cuadrado con papel vegetal.", "Funde el chocolate troceado junto con la mantequilla al microondas (en tandas cortas) o al baño maría.", "En un bol, bate los huevos con el azúcar sin blanquearlos demasiado (no queremos aire).", "Añade la mezcla de chocolate templado a los huevos y remueve.", "Tamiza la harina sobre la mezcla e incorpórala con una espátula. Añade las nueces troceadas.", "Vierte en el molde y hornea unos 25 minutos. El centro debe quedar ligeramente húmedo."]}'),
('{"name": "Crepes Dulces Franceses (Postre)", "meal_type": "desayuno", "price": "economica", "difficulty": "facil", "health": "no saludable", "diet_type": "vegetariano", "allergens": ["gluten", "lactosa", "huevo"], "ingredients": [{"name": "Harina de trigo", "quantity": 125, "unit": "g"}, {"name": "Leche entera", "quantity": 250, "unit": "ml"}, {"name": "Huevos", "quantity": 2, "unit": "unidades"}, {"name": "Mantequilla derretida", "quantity": 25, "unit": "g"}, {"name": "Azúcar", "quantity": 15, "unit": "g"}, {"name": "Mantequilla para la sartén", "quantity": 10, "unit": "g"}], "instructions": ["En el vaso de la batidora, pon la leche, los huevos, la harina, el azúcar y la mantequilla derretida. Bate hasta que no queden grumos.", "Deja reposar la masa en la nevera durante unos 30 minutos.", "Calienta una sartén antiadherente o crepera y engrasa con una pizca de mantequilla.", "Vierte un cucharón de masa y mueve la sartén rápido en círculos para extenderla muy fina.", "Cuando los bordes se doren, dale la vuelta con una espátula y cocina 30 segundos más. Rellena al gusto."]}');